{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2173-07-28 23:00:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee. I’ll be taking care of you tonight. I understand you’ve been having worsening abdominal pain near your G-tube site?"
    },
    {
      "turn_number": 2,
      "time": "2173-07-28 23:01:30",
      "speaker": "Patient",
      "text": "Yes, it’s been going on for months, but the last two weeks it’s gotten much worse. It’s a dull pain in the upper left side, especially when I’m getting my tube feeds."
    },
    {
      "turn_number": 3,
      "time": "2173-07-28 23:03:00",
      "speaker": "Doctor",
      "text": "I see. And you mentioned dry heaving too? Any nausea, vomiting, or fever?"
    },
    {
      "turn_number": 4,
      "time": "2173-07-28 23:04:15",
      "speaker": "Patient",
      "text": "Just dry heaving sometimes. No vomiting, no fever. I’ve been worried it’s something serious with the tube or infection."
    },
    {
      "turn_number": 5,
      "time": "2173-07-28 23:05:45",
      "speaker": "Doctor",
      "text": "We checked a chest X-ray to make sure there’s no free air, which would suggest a perforation, and it was normal. Your abdomen isn’t distended, and there’s no redness or signs of infection at the G-tube site."
    },
    {
      "turn_number": 6,
      "time": "2173-07-28 23:07:10",
      "speaker": "Patient",
      "text": "So it’s not infected? That’s a relief. But why does it hurt so much now?"
    },
    {
      "turn_number": 7,
      "time": "2173-07-28 23:08:30",
      "speaker": "Doctor",
      "text": "Given your history, the pain is likely related to your known marginal ulcer. Bariatric surgery was consulted and they don’t think you need more imaging or surgery right now."
    },
    {
      "turn_number": 8,
      "time": "2173-07-28 23:10:00",
      "speaker": "Patient",
      "text": "I had that ulcer problem before. Is it acting up again?"
    },
    {
      "turn_number": 9,
      "time": "2173-07-28 23:11:20",
      "speaker": "Doctor",
      "text": "Yes, it’s likely an exacerbation. Your labs are normal—no signs of infection or organ issues. We’ll focus on pain control and continue your ulcer medications through the tube."
    },
    {
      "turn_number": 10,
      "time": "2173-07-28 23:13:00",
      "speaker": "Patient",
      "text": "I got some Dilaudid in the ER and it helped. Will I keep getting that?"
    },
    {
      "turn_number": 11,
      "time": "2173-07-28 23:14:15",
      "speaker": "Doctor",
      "text": "We’ll manage your pain with IV Dilaudid as needed. Once we’re sure your pain is stable, we’ll switch you to oral oxycodone for discharge."
    },
    {
      "turn_number": 12,
      "time": "2173-07-28 23:15:45",
      "speaker": "Patient",
      "text": "And my tube feeds? I’ve been off them because of the pain."
    },
    {
      "turn_number": 13,
      "time": "2173-07-28 23:17:00",
      "speaker": "Doctor",
      "text": "We restarted your continuous tube feeds. You were given D5NS in the ED to prevent low blood sugar, but now that feeds are back on, you should be okay."
    },
    {
      "turn_number": 14,
      "time": "2173-07-28 23:18:30",
      "speaker": "Patient",
      "text": "Good. I’ve had those hypoglycemia episodes before. Scary when I pass out."
    },
    {
      "turn_number": 15,
      "time": "2173-07-28 23:20:00",
      "speaker": "Doctor",
      "text": "Exactly. That’s why we keep the feeds running. We’ll continue your sucralfate and lansoprazole through the tube to protect your stomach lining."
    },
    {
      "turn_number": 16,
      "time": "2173-07-29 10:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs this morning are stable. Pain seems better? We’re planning to discharge you later today."
    },
    {
      "turn_number": 17,
      "time": "2173-07-29 10:16:30",
      "speaker": "Patient",
      "text": "Yes, much better. Still some ache, but not like before. What should I do when I get home?"
    },
    {
      "turn_number": 18,
      "time": "2173-07-29 10:18:00",
      "speaker": "Doctor",
      "text": "You’ll go home on liquid oxycodone for pain as needed. Keep taking your regular meds—rifaximin, sucralfate, lansoprazole, and now we’re adding B12 and multivitamins."
    },
    {
      "turn_number": 19,
      "time": "2173-07-29 10:19:45",
      "speaker": "Patient",
      "text": "B12? I didn’t take that before."
    },
    {
      "turn_number": 20,
      "time": "2173-07-29 10:21:00",
      "speaker": "Doctor",
      "text": "After gastric bypass, many patients need B12 supplements. It’s a preventive step. Also, please follow up with pain management—we’d like you to see a specialist."
    },
    {
      "turn_number": 21,
      "time": "2173-07-29 10:22:30",
      "speaker": "Patient",
      "text": "Okay, I’ll make the appointment. And my ulcer—should I get checked again?"
    },
    {
      "turn_number": 22,
      "time": "2173-07-29 10:24:00",
      "speaker": "Doctor",
      "text": "Yes, you’re scheduled for an EGD later this month to check the ulcer. For now, keep the feeds going, take your meds, and call if pain worsens or you develop fever."
    },
    {
      "turn_number": 23,
      "time": "2173-07-29 10:25:30",
      "speaker": "Patient",
      "text": "Got it. Thank you for explaining everything. I feel a lot better knowing it’s not an infection or something torn."
    },
    {
      "turn_number": 24,
      "time": "2173-07-29 10:27:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll get the discharge papers ready. You should be home within a few hours."
    },
    {
      "turn_number": 25,
      "time": "2173-07-29 15:30:00",
      "speaker": "Doctor",
      "text": "Just a final check before discharge. Pain still manageable?"
    },
    {
      "turn_number": 26,
      "time": "2173-07-29 15:31:15",
      "speaker": "Patient",
      "text": "Yes, I’ve only needed one dose of oxycodone this morning. I’m ready to go home."
    },
    {
      "turn_number": 27,
      "time": "2173-07-29 15:32:30",
      "speaker": "Doctor",
      "text": "Perfect. Remember: take your meds, keep the feeds running, and follow up with pain clinic and GI. We’ll see you in follow-up soon."
    },
    {
      "turn_number": 28,
      "time": "2173-07-29 15:34:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I appreciate all your help."
    }
  ],
  "summary": {
    "admission_start": "2173-07-28 22:48:00",
    "admission_end": "2173-07-29 19:42:00",
    "summary_paragraph": "The patient was admitted with acute-on-chronic left upper quadrant abdominal pain near her G-tube site, worsened over two weeks. Evaluation showed no signs of infection, obstruction, or free air on imaging. The pain was attributed to her known marginal ulcer, and she responded well to IV pain control with Dilaudid. Tube feeds were restarted to prevent hypoglycemia, and ulcer prophylaxis was continued. She was transitioned to liquid oxycodone for discharge and advised to follow up with pain management and GI for a planned EGD. The patient was discharged home in stable condition.",
    "problems": [
      "Abdominal pain, left upper quadrant",
      "Other chronic pain",
      "Chronic gastrojejunal ulcer without mention of hemorrhage or perforation, without mention of obstruction",
      "Other and unspecified postsurgical nonabsorption",
      "Gastrostomy status",
      "Bariatric surgery status",
      "Unspecified disorder of pancreatic internal secretion",
      "Depressive disorder, not elsewhere classified",
      "Anxiety state, unspecified",
      "Insomnia, unspecified",
      "Esophageal reflux",
      "Polycystic ovaries",
      "Other chronic nonalcoholic liver disease",
      "Personal history of Methicillin resistant Staphylococcus aureus"
    ]
  }
}
